import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"微软翻译接口申请及配置","description":"","frontmatter":{"plugin":"windingwind/zotero-pdf-translate"},"headers":[],"relativePath":"user-guide/plugins/translate/microsoft.md","filePath":"wiki/user-guide/plugins/translate/microsoft.md"}`),u=Object.assign({name:`user-guide/plugins/translate/microsoft.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginstranslatemicrosoft.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`微软翻译接口申请及配置`,tabindex:`-1`},[o(`微软翻译接口申请及配置 `),i(`a`,{class:`header-anchor`,href:`#微软翻译接口申请及配置`,"aria-label":`Permalink to “微软翻译接口申请及配置”`},`​`)],-1),r(s),u[2]||=a(`<h2 id="_1-接口申请" tabindex="-1">1. 接口申请 <a class="header-anchor" href="#_1-接口申请" aria-label="Permalink to “1. 接口申请”">​</a></h2><p>打开 <a href="https://azure.microsoft.com/zh-cn/pricing/purchase-options/azure-account/?icid=ai-services" target="_blank" rel="noreferrer">微软的接口平台</a></p><p>点击「免费试用 Azure」，会提示你登录微软账号，如果你没有账号，可以申请一个后再登录。</p><p><img src="/assets/microsoft-1.BaBVWK47.png" alt="开通页面" width="1080" height="381"></p><p>跳转到登录页面，并使用账号登录。</p><p><img src="/assets/microsoft-2.oc6CXdT8.png" alt="登录页面" width="494" height="494"></p><p>弹出开通服务的窗口，勾选第一个同意，点击「下一步」：</p><p><img src="/assets/microsoft-3.DLOmQJDY.png" alt="开通步骤" width="1080" height="631"></p><p>进行短信验证：</p><p><img src="/assets/microsoft-4.C147Pg26.png" alt="验证" width="1080" height="580"></p><p>可能需要绑定信用卡：</p><p><img src="/assets/microsoft-5.Cd5hvH5d.png" alt="绑定信用卡" width="1080" height="581"></p><p>然后直接下一步，可能会遇到邮箱或其他验证方式，直接按照操作说明进行验证。</p><p>打开 <a href="https://portal.azure.com/#create/Microsoft.CognitiveServicesTextTranslation" target="_blank" rel="noreferrer">微软翻译设置</a> 申请翻译服务：</p><p><img src="/assets/microsoft-6.HFGsqmM5.png" alt="新建翻译服务" width="752" height="361"></p><p><img src="/assets/microsoft-7.CbLTjESK.png" alt="创建服务窗口" width="777" height="280"></p><p>注意上面请选择「East Asia」，后面密钥设置时需要用到这个参数。</p><p>点击审阅并创建：</p><p><img src="/assets/microsoft-8.JXX1aYD5.png" alt="点击创建" width="718" height="596"></p><p>等待服务创建完成，你可以在 Azure 主页中看到你的新翻译服务，点击下面的链接 <a href="https://portal.azure.com/#home" target="_blank" rel="noreferrer">https://portal.azure.com/#home</a>。</p><p><img src="/assets/microsoft-9.wMrAO2c0.png" alt="查看翻译服务" width="1080" height="390"></p><p><img src="/assets/microsoft-10.DdnD_Xib.png" alt="翻译服务详情" width="1080" height="676"></p><p>如果上面第 4 个 位置/区域 是全球，可不必复制。</p><h2 id="_2-翻译插件配置" tabindex="-1">2. 翻译插件配置 <a class="header-anchor" href="#_2-翻译插件配置" aria-label="Permalink to “2. 翻译插件配置”">​</a></h2><p>打开翻译插件的设置：</p><p><img src="/assets/microsoft-11.CgoFmWXm.png" alt="翻译插件设置" width="800" height="600"></p><p>上图第三步，复制密钥时，请按照 <code>secretKey#region</code> 的格式进行。<code>scretKey</code> 是下图的第三步，<code>region</code> 是下图第四步。注意如果 <code>region</code> 是<code>全球 global</code>，可以不必填 <code>region</code>，只复制 <code>scretKey</code> 即可。</p><p><img src="/assets/microsoft-10.DdnD_Xib.png" alt="配置参数信息" width="1080" height="676"></p>`,28),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};